urllib3.util.wait.wait_for_socket:
def wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    global wait_for_socket
    if _have_working_poll():
        wait_for_socket = poll_wait_for_socket
    elif hasattr(select, 'select'):
        wait_for_socket = select_wait_for_socket
    return wait_for_socket(sock, read, write, timeout)

urllib3.util.wait._have_working_poll:
def _have_working_poll() -> bool:
    try:
        poll_obj = select.poll()
        poll_obj.poll(0)
    except (AttributeError, OSError):
        return False
    else:
        return True

urllib3.util.wait.poll_wait_for_socket:
def poll_wait_for_socket(sock: socket.socket, read: bool = False, write: bool = False, timeout: float | None = None) -> bool:
    if (not read and not write):
        raise RuntimeError('must specify at least one of read=True, write=True')
    mask = 0
    if read:
        mask |= select.POLLIN
    if write:
        mask |= select.POLLOUT
    poll_obj = select.poll()
    poll_obj.register(sock, mask)

    def do_poll(t: float | None) -> list[tuple[(int, int)]]:
        if t is not None:
            t *= 1000
        return poll_obj.poll(t)
    return bool(do_poll(timeout))

urllib3.contrib.emscripten.fetch._show_t:
def _show_timeout_warning() -> None:
    global _SHOWN_TIMEOUT_WARNING
    if not _SHOWN_TIMEOUT_WARNING:
        _SHOWN_TIMEOUT_WARNING = True
        message = 'Warning: Timeout is not available on main browser thread'
        js.console.warn(message)

urllib3.contrib.emscripten.fetch.send_re:
def send_request(request: EmscriptenRequest) -> EmscriptenResponse:
    if has_jspi():
        return send_jspi_request(request, False)
    elif is_in_node():
        raise _RequestError(message=NODE_JSPI_ERROR, request=request, response=None)
    try:
        js_xhr = js.XMLHttpRequest.new()
        if not is_in_browser_main_thread():
            js_xhr.responseType = 'arraybuffer'
            if request.timeout:
                js_xhr.timeout = int(request.timeout * 1000)
        else:
            js_xhr.overrideMimeType('text/plain; charset=ISO-8859-15')
            if request.timeout:
                _show_timeout_warning()
        js_xhr.open(request.method, request.url, False)
        for (name, value) in request.headers.items():
            if name.lower() not in HEADERS_TO_IGNORE:
                js_xhr.setRequestHeader(name, value)
        js_xhr.send(to_js(request.body))
        headers = dict(Parser().parsestr(js_xhr.getAllResponseHeaders()))
        if not is_in_browser_main_thread():
            body = js_xhr.response.to_py().tobytes()
        else:
            body = js_xhr.response.encode('ISO-8859-15')
        return EmscriptenResponse(status_code=js_xhr.status, headers=headers, body=body, request=request)
    except JsException as err:
        if err.name == 'TimeoutError':
            raise _TimeoutError(err.message, request=request)
        elif err.name == 'NetworkError':
            raise _RequestError(err.message, request=request)
        else:
            raise _RequestError(err.message, request=request)

urllib3.util.ssl_match_hostname.match_ho:
def match_hostname(cert: _TYPE_PEER_CERT_RET_DICT | None, hostname: str, hostname_checks_common_name: bool = False) -> None:
    """Verify that *cert* (in decoded format as returned by
    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125
    rules are followed, but IP addresses are not accepted for *hostname*.

    CertificateError is raised on failure. On success, the function
    returns nothing.
    """
    if not cert:
        raise ValueError('empty or no certificate, match_hostname needs a SSL socket or SSL context with either CERT_OPTIONAL or CERT_REQUIRED')
    try:
        if '%' in hostname:
            host_ip = ipaddress.ip_address(hostname[:hostname.rfind('%')])
        else:
            host_ip = ipaddress.ip_address(hostname)
    except ValueError:
        host_ip = None
    dnsnames = []
    san: tuple[(tuple[(str, str)], ...)] = cert.get('subjectAltName', ())
    key: str
    value: str
    for (key, value) in san:
        if key == 'DNS':
            if (host_ip is None and _dnsname_match(value, hostname)):
                return
            dnsnames.append(value)
        elif key == 'IP Address':
            if (host_ip is not None and _ipaddress_match(value, host_ip)):
                return
            dnsnames.append(value)
    if (hostname_checks_common_name and host_ip is None and not dnsnames):
        for sub in cert.get('subject', ()):
            for (key, value) in sub:
                if key == 'commonName':
                    if _dnsname_match(value, hostname):
                        return
                    dnsnames.append(value)
    if len(dnsnames) > 1:
        raise CertificateError("hostname %r doesn't match either of %s" % (hostname, ', '.join(map(repr, dnsnames))))
    elif len(dnsnames) == 1:
        raise CertificateError(f"hostname {hostname!r} doesn't match {dnsnames[0]!r}")
    else:
        raise CertificateError('no appropriate subjectAltName fields were found')

urllib3.util.ssl_match_hostname._dnsname:
def _dnsname_match(dn: typing.Any, hostname: str, max_wildcards: int = 1) -> typing.Match[str] | None | bool:
    """Matching according to RFC 6125, section 6.4.3

    http://tools.ietf.org/html/rfc6125#section-6.4.3
    """
    pats = []
    if not dn:
        return False
    parts = dn.split('.')
    leftmost = parts[0]
    remainder = parts[1:]
    wildcards = leftmost.count('*')
    if wildcards > max_wildcards:
        raise CertificateError('too many wildcards in certificate DNS name: ' + repr(dn))
    if not wildcards:
        return bool(dn.lower() == hostname.lower())
    if leftmost == '*':
        pats.append('[^.]+')
    elif (leftmost.startswith('xn--') or hostname.startswith('xn--')):
        pats.append(re.escape(leftmost))
    else:
        pats.append(re.escape(leftmost).replace('\\*', '[^.]*'))
    for frag in remainder:
        pats.append(re.escape(frag))
    pat = re.compile('\\A' + '\\.'.join(pats) + '\\Z', re.IGNORECASE)
    return pat.match(hostname)

idna.core.decode:
def decode(s: Union[(str, bytes, bytearray)], strict: bool = False, uts46: bool = False, std3_rules: bool = False, display: bool = False) -> str:
    """Decode an A-label-encoded domain name back to Unicode.

    Splits the input on label separators (see :func:`encode` for the
    rules), decodes each label with :func:`ulabel`, and rejoins them
    with ``.``. Optionally pre-processes the input through
    :func:`uts46_remap`.

    :param s: The domain name to decode.
    :param strict: If ``True``, only ``U+002E`` is recognised as a label
        separator.
    :param uts46: If ``True``, apply UTS #46 mapping before decoding.
    :param std3_rules: Forwarded to :func:`uts46_remap` when ``uts46`` is
        ``True``.
    :param display: If ``True``, any ``xn--`` label that fails IDNA
        validation is passed through unchanged (lowercased) rather than
        aborting the whole call. Intended for "decode for display"
        consumers (e.g. URL libraries, HTTP clients) that want to show
        the user the label as it appears on the wire when it cannot be
        rendered as Unicode. Matches the per-label recovery prescribed
        by UTS #46 §4 and the WHATWG URL "domain to Unicode" algorithm.
    :returns: The decoded domain as a Unicode string.
    :raises IDNAError: If the input is not valid ASCII, contains an
        invalid label, or is empty.
    """
    if not isinstance(s, str):
        try:
            s = str(s, 'ascii')
        except (UnicodeDecodeError, TypeError) as err:
            raise IDNAError('Invalid ASCII in A-label') from err
    if len(s) > _max_input_length:
        raise IDNAError('Domain too long')
    if uts46:
        s = uts46_remap(s, std3_rules, False)
    if not valid_string_length(s, trailing_dot=True):
        raise IDNAError('Domain too long')
    trailing_dot = False
    result = []
    labels = (s.split('.') if strict else _unicode_dots_re.split(s))
    if (not labels or labels == ['']):
        raise IDNAError('Empty domain')
    if not labels[-1]:
        del labels[-1]
        trailing_dot = True
    for label in labels:
        try:
            u = ulabel(label)
        except IDNAError:
            if (display and label[:4].lower() == 'xn--'):
                u = label.lower()
            else:
                raise
        if u:
            result.append(u)
        else:
            raise IDNAError('Empty label')
    if trailing_dot:
        result.append('')
    return '.'.join(result)

urllib3.util.connection._set_socket_opti:
def _set_socket_options(sock: socket.socket, options: _TYPE_SOCKET_OPTIONS | None) -> None:
    if options is None:
        return
    for opt in options:
        sock.setsockopt(*opt)

idna.core._combining_class:
def _combining_class(cp: int) -> int:
    v = unicodedata.combining(chr(cp))
    if (v == 0 and not unicodedata.name(chr(cp))):
        raise ValueError('Unknown character in unicodedata')
    return v

requests.utils.get_encoding_from_headers:
def get_encoding_from_headers(headers):
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    :rtype: str
    """
    content_type = headers.get('content-type')
    if not content_type:
        return None
    (content_type, params) = _parse_content_type_header(content_type)
    if 'charset' in params:
        return params['charset'].strip('\'"')
    if 'text' in content_type:
        return 'ISO-8859-1'
    if 'application/json' in content_type:
        return 'utf-8'

requests.utils.get_unicode_from_response:
def get_unicode_from_response(r):
    """Returns the requested content back in unicode.

    :param r: Response object to get unicode content from.

    Tried:

    1. charset from content-type
    2. fall back and replace all unicode characters

    :rtype: str
    """
    warnings.warn('In requests 3.0, get_unicode_from_response will be removed. For more information, please see the discussion on issue #2266. (This warning should only appear once.)', DeprecationWarning)
    tried_encodings = []
    encoding = get_encoding_from_headers(r.headers)
    if encoding:
        try:
            return str(r.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)
    try:
        return str(r.content, encoding, errors='replace')
    except TypeError:
        return r.content

requests.utils._parse_content_type_heade:
def _parse_content_type_header(header):
    """Returns content type and parameters from given header

    :param header: string
    :return: tuple containing content type and dictionary of
         parameters
    """
    tokens = header.split(';')
    (content_type, params) = (tokens[0].strip(), tokens[1:])
    params_dict = {}
    items_to_strip = '"\' '
    for param in params:
        param = param.strip()
        if param:
            (key, value) = (param, True)
            index_of_equals = param.find('=')
            if index_of_equals != -1:
                key = param[:index_of_equals].strip(items_to_strip)
                value = param[index_of_equals + 1:].strip(items_to_strip)
            params_dict[key.lower()] = value
    return (content_type, params_dict)
